}

fn begin_activation(
    &mut self,
    id: &str,
    cell: &mut Cell,
    activation: Activation,
    effects: &mut Vec<Effect>,
) {
    debug_assert!(self.has_capacity());
    cell.waiting_for = None;
    let op = self.cell_op(id);
    match activation {
        Activation::Claim(claim) => {
            set_phase(
                &mut self.occupied,
                cell,
                Phase::Acquiring {
                    op,
                    claim: claim.clone(),
