            effects.push(Effect::CasOwner {
                op,
                cell: id.to_string(),
                guard: claim.guard,
                epoch: claim.epoch,
                takeover: claim.takeover,
            });
        }
        Activation::Restore(spec) => {
            set_phase(
                &mut self.occupied,
                cell,
                Phase::Restoring {
                    op,
                    spec: spec.clone(),
                },
            );
            effects.push(Effect::Restore {
                op,
                cell: id.to_string(),
                spec,
            });
        }
    }
}

fn activate_or_wait(
    &mut self,
    id: &str,
    cell: &mut Cell,
    activation: Activation,
    effects: &mut Vec<Effect>,
) {
    if cell.requests.is_empty() && !cell.alarm_wake && !cell.resume_demand {
        set_phase(
            &mut self.occupied,
            cell,
            match activation {
