        Ok(CasOutcome::Applied) => {
            let spec = RestoreSpec {
                epoch: claim.epoch,
                fresh: matches!(claim.guard, CasGuard::Absent),
                took_over: claim.takeover,
                resume_local: false,
                prior: claim.prior.clone(),
            };
