                set_phase(
                    &mut self.occupied,
                    &mut cell,
                    Phase::Dormant { epoch: spec.epoch },
                );
            } else {
                let next = self.cell_op(&id);
                set_phase(
                    &mut self.occupied,
                    &mut cell,
                    Phase::Restoring {
                        op: next,
                        spec: spec.clone(),
                    },
                );
                effects.push(Effect::Restore {
                    op: next,
                    cell: id.clone(),
                    spec,
                });
            }
        }
        Ok(CasOutcome::Rejected) => {
            let next = self.cell_op(&id);
            set_phase(
                &mut self.occupied,
                &mut cell,
